import { Box, Container, Grid, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";
import LeadFormCard from "./LeadFormCard";

export default function HeroSection() {
  const { brand, hero } = masterData;

  return (
    <Box
      sx={{
        background: "linear-gradient(180deg, #F0F6FF 0%, #FFFFFF 55%, #FFFFFF 100%)",
        pt: { xs: 2, md: 3 },
        pb: { xs: 4, md: 6 },
      }}
    >
      <Container maxWidth="lg">
        <Stack direction="row" alignItems="center" spacing={1.25} sx={{ mb: { xs: 3, md: 4 } }}>
          <Box
            component="img"
            src={brand.logo}
            alt={brand.name}
            sx={{ width: 36, height: 36 }}
          />
          <Typography
            sx={{
              fontWeight: 800,
              fontSize: 15,
              letterSpacing: "0.06em",
              color: "#0A2540",
            }}
          >
            {brand.name}
          </Typography>
        </Stack>

        <Grid container spacing={{ xs: 4, md: 5 }} alignItems="center">
          <Grid size={{ xs: 12, md: 7 }}>
            <Typography
              variant="h3"
              sx={{
                fontWeight: 800,
                color: "primary.main",
                fontSize: { xs: "1.75rem", sm: "2.25rem", md: "2.6rem" },
                lineHeight: 1.2,
                mb: 2,
                maxWidth: 560,
              }}
            >
              {hero.headline}
            </Typography>

            <Typography
              sx={{ fontWeight: 700, color: "#0A2540", fontSize: { xs: 16, md: 18 }, mb: 1.5 }}
            >
              {hero.subheadline}
            </Typography>

            <Typography
              sx={{
                color: "text.secondary",
                fontSize: { xs: 14, md: 15 },
                lineHeight: 1.7,
                mb: 3,
                maxWidth: 540,
              }}
            >
              {hero.description}
            </Typography>

            <Stack
              direction="row"
              spacing={{ xs: 2, md: 3 }}
              flexWrap="wrap"
              useFlexGap
              sx={{ mb: 3 }}
            >
              {hero.stats.map((stat) => {
                const Icon = getIcon(stat.icon);
                return (
                  <Stack key={stat.id} direction="row" spacing={1} alignItems="center">
                    <Box
                      sx={{
                        width: 36,
                        height: 36,
                        borderRadius: "50%",
                        bgcolor: "#E8F1FF",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                      }}
                    >
                      <Icon sx={{ color: "primary.main", fontSize: 20 }} />
                    </Box>
                    <Typography sx={{ fontSize: 13, fontWeight: 600, color: "#0A2540" }}>
                      {stat.label}
                    </Typography>
                  </Stack>
                );
              })}
            </Stack>

            <Box sx={{ position: "relative", display: "inline-block", maxWidth: "100%" }}>
              <Box
                component="img"
                src={hero.image}
                alt="Doctor"
                sx={{
                  width: { xs: "100%", sm: 380, md: 420 },
                  maxWidth: "100%",
                  height: { xs: 280, sm: 360, md: 400 },
                  objectFit: "cover",
                  objectPosition: "top",
                  borderRadius: 3,
                }}
              />
              <Box
                component="img"
                src={hero.badge}
                alt="Better Doctors"
                sx={{
                  position: "absolute",
                  top: { xs: 12, md: 20 },
                  right: { xs: -8, md: -24 },
                  width: { xs: 72, md: 96 },
                  height: { xs: 72, md: 96 },
                }}
              />
              <Box
                component="img"
                src={hero.cpdBadge}
                alt="CPD Accredited"
                sx={{
                  position: "absolute",
                  bottom: 16,
                  left: 16,
                  width: { xs: 64, md: 80 },
                  height: { xs: 64, md: 80 },
                  bgcolor: "rgba(255,255,255,0.92)",
                  borderRadius: "50%",
                  p: 0.5,
                }}
              />
            </Box>
          </Grid>

          <Grid size={{ xs: 12, md: 5 }}>
            <LeadFormCard />
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
}
